189	static char *split_nicks(const char *cmd, char **pre, char **nicks, char **post, int arg)
190	{
191		char *p;
192	
193		*pre = g_strdup(cmd);
194		*post = *nicks = NULL;
195	
196		if (**pre == '@') {
197			/* the message-tags "add" one space separated argument
198			   in front of the non message-tagged IRC commands. So
199			   the nicks are now off-set by one to the right. */
200			arg++;
201		}
202	
203		for (p = *pre; *p != '\0'; p++) {
204			if (*p != ' ')
205				continue;
206	
207			if (arg == 1) {
208				/* text after nicks */
209				*p++ = '\0';
210				while (*p == ' ') p++;
211				*post = p;
212				break;
213			}
214	
215			/* find nicks */
216			while (p[1] == ' ') p++;
217			if (--arg == 1) {
218				*p = '\0';
219				*nicks = p+1;
220			}
221		}
