227	static void mode_set(IRC_SERVER_REC *server, GString *str,
228			     char type, char mode, int user)
229	{
230		g_return_if_fail(str != NULL);
231	
232		if (type == '-')
233			mode_remove(server, str, mode, user);
234	        else
235			mode_add_sorted(server, str, mode, NULL, user);
236	}
