238	static void mode_set_arg(IRC_SERVER_REC *server, GString *str,
239				 char type, char mode, const char *arg, int user)
240	{
241		g_return_if_fail(str != NULL);
242		g_return_if_fail(type == '-' || arg != NULL);
243	
244		if (type == '-')
245			mode_remove(server, str, mode, user);
246	        else
247			mode_add_sorted(server, str, mode, arg, user);
248	}
