264	void modes_type_b(IRC_CHANNEL_REC *channel, const char *setby, char type,
265			  char mode, char *arg, GString *newmode)
266	{
267		if (mode == 'k') {
268			if (*arg == '\0' && type == '+')
269				arg = channel->key != NULL ? channel->key : "???";
270	
271			if (arg != channel->key) {
272				g_free_and_null(channel->key);
273				if (type == '+')
274					channel->key = g_strdup(arg);
275			}
276		}
