799			      WI_ITEM_REC *item)
800	{
801	        IRC_CHANNEL_REC *channel;
802		char *nicks;
803	
804	        CMD_IRC_SERVER(server);
805	
806		nicks = get_nicks(server, item, data, 0, 0, &channel);
807		if (nicks != NULL && *nicks != '\0')
808			channel_set_singlemode(channel, nicks, "+v");
809		g_free_not_null(nicks);
810	}
811	
812	/* SYNTAX: DEVOICE <nicks> */
813	static void cmd_devoice(const char *data, IRC_SERVER_REC *server,
814				WI_ITEM_REC *item)
815	{
816	        IRC_CHANNEL_REC *channel;
817		char *nicks;
818	
819	        CMD_IRC_SERVER(server);
820	
821		nicks = get_nicks(server, item, data, -1, 1, &channel);
822		if (nicks != NULL && *nicks != '\0')
823			channel_set_singlemode(channel, nicks, "-v");
824		g_free_not_null(nicks);
825	}
826	
827	/* SYNTAX: MODE <your nick>|<channel> [<mode> [<mode parameters>]] */
828	static void cmd_mode(const char *data, IRC_SERVER_REC *server,
829			     IRC_CHANNEL_REC *channel)
830	{
831		IRC_CHANNEL_REC *chanrec;
832		char *target, *mode;
833		void *free_arg;
834	
835	        CMD_IRC_SERVER(server);
836	
837		if (*data == '+' || *data == '-') {
838			target = "*";
839			if (!cmd_get_params(data, &free_arg, 1 | PARAM_FLAG_GETREST | PARAM_FLAG_STRIP_TRAILING_WS, &mode))
840				return;
841		} else {
842			if (!cmd_get_params(data, &free_arg, 2 | PARAM_FLAG_GETREST | PARAM_FLAG_STRIP_TRAILING_WS, &target, &mode))
843				return;
844		}
845	
846		if (g_strcmp0(target, "*") == 0) {
847			if (!IS_IRC_CHANNEL(channel))
848				cmd_param_error(CMDERR_NOT_JOINED);
849	
850			target = channel->name;
851		}
852		if (*target == '\0') cmd_param_error(CMDERR_NOT_ENOUGH_PARAMS);
853	
854		if (*mode == '\0') {
855			chanrec = irc_channel_find(server, target);
856			if (chanrec != NULL)
857				target = chanrec->name;
858	
859			irc_send_cmdv(server, "MODE %s", target);
860		} else if (server_ischannel(SERVER(server), target))
861			channel_set_mode(server, target, mode);
862		else {
863			if (g_ascii_strcasecmp(target, server->nick) == 0) {
864				server_redirect_event(server, "mode user", 1, target, -1, NULL,
865						      "event mode", "requested usermode change", NULL);
866			}
867	
868			irc_send_cmdv(server, "MODE %s %s", target, mode);
869		}
870	
871		cmd_params_free(free_arg);
872	}
873	
874	void modes_server_init(IRC_SERVER_REC *server)
875	{
876		server->modes['b'].func = modes_type_a;
877		server->modes['e'].func = modes_type_a;
878		server->modes['I'].func = modes_type_a;
879	
880		server->modes['h'].func = modes_type_prefix;
881		server->modes['h'].prefix = '%';
882		server->modes['o'].func = modes_type_prefix;
883		server->modes['o'].prefix = '@';
884		server->modes['O'].func = modes_type_prefix;
885		server->modes['O'].prefix = '@';
886		server->modes['v'].func = modes_type_prefix;
887		server->modes['v'].prefix = '+';
888	
889		server->prefix['%'] = 'h';
890		server->prefix['@'] = 'o';
891		server->prefix['+'] = 'v';
892	
893		server->modes['k'].func = modes_type_b;
894		server->modes['l'].func = modes_type_c;
895	}
896	
897	void modes_init(void)
898	{
899		settings_add_str("misc", "opermode", "");
900		settings_add_int("misc", "max_wildcard_modes", 6);
901	
902		signal_add("event 221", (SIGNAL_FUNC) event_user_mode);
903		signal_add("event 305", (SIGNAL_FUNC) event_unaway);
904		signal_add("event 306", (SIGNAL_FUNC) event_away);
905		signal_add("event 381", (SIGNAL_FUNC) event_oper);
906		signal_add("event mode", (SIGNAL_FUNC) event_mode);
907	        signal_add("requested usermode change", (SIGNAL_FUNC) sig_req_usermode_change);
908	
909		command_bind_irc("op", NULL, (SIGNAL_FUNC) cmd_op);
910		command_bind_irc("deop", NULL, (SIGNAL_FUNC) cmd_deop);
911		command_bind_irc("voice", NULL, (SIGNAL_FUNC) cmd_voice);
912		command_bind_irc("devoice", NULL, (SIGNAL_FUNC) cmd_devoice);
913		command_bind_irc("mode", NULL, (SIGNAL_FUNC) cmd_mode);
914	
915		command_set_options("op", "yes");
916	}
917	
918	void modes_deinit(void)
919	{
920		signal_remove("event 221", (SIGNAL_FUNC) event_user_mode);
921		signal_remove("event 305", (SIGNAL_FUNC) event_unaway);
922		signal_remove("event 306", (SIGNAL_FUNC) event_away);
923		signal_remove("event 381", (SIGNAL_FUNC) event_oper);
924		signal_remove("event mode", (SIGNAL_FUNC) event_mode);
925	        signal_remove("requested usermode change", (SIGNAL_FUNC) sig_req_usermode_change);
926	
927		command_unbind("op", (SIGNAL_FUNC) cmd_op);
928		command_unbind("deop", (SIGNAL_FUNC) cmd_deop);
929		command_unbind("voice", (SIGNAL_FUNC) cmd_voice);
930		command_unbind("devoice", (SIGNAL_FUNC) cmd_devoice);
931		command_unbind("mode", (SIGNAL_FUNC) cmd_mode);
932	}
