227	static void mode_set(IRC_SERVER_REC *server, GString *str,
228			     char type, char mode, int user)
229	{
230		g_return_if_fail(str != NULL);
231	
232		if (type == '-')
233			mode_remove(server, str, mode, user);
234	        else
235			mode_add_sorted(server, str, mode, NULL, user);
236	}
237	
238	static void mode_set_arg(IRC_SERVER_REC *server, GString *str,
239				 char type, char mode, const char *arg, int user)
240	{
241		g_return_if_fail(str != NULL);
242		g_return_if_fail(type == '-' || arg != NULL);
243	
244		if (type == '-')
245			mode_remove(server, str, mode, user);
246	        else
247			mode_add_sorted(server, str, mode, arg, user);
248	}
249	
250	/* Mode that needs a parameter of a mask for both setting and removing
251	   (eg: bans) */
252	void modes_type_a(IRC_CHANNEL_REC *channel, const char *setby, char type,
253			  char mode, char *arg, GString *newmode)
254	{
255		if (mode == 'b') {
256			if (type == '+')
257				banlist_add(channel, arg, setby, time(NULL));
258			else
259				banlist_remove(channel, arg, setby);
260		}
261	}
262	
263	/* Mode that needs parameter for both setting and removing (eg: +k) */
264	void modes_type_b(IRC_CHANNEL_REC *channel, const char *setby, char type,
265			  char mode, char *arg, GString *newmode)
266	{
267		if (mode == 'k') {
268			if (*arg == '\0' && type == '+')
269				arg = channel->key != NULL ? channel->key : "???";
270	
271			if (arg != channel->key) {
272				g_free_and_null(channel->key);
273				if (type == '+')
274					channel->key = g_strdup(arg);
275			}
276		}
277	
278		mode_set_arg(channel->server, newmode, type, mode, arg, FALSE);
279	}
