281	/* Mode that needs parameter only for adding */
282	void modes_type_c(IRC_CHANNEL_REC *channel, const char *setby,
283			  char type, char mode, char *arg, GString *newmode)
284	{
285		if (mode == 'l') {
286			channel->limit = type == '-' ? 0 : atoi(arg);
287		}
288	
289		mode_set_arg(channel->server, newmode, type, mode, arg, FALSE);
290	}
291	
292	/* Mode that takes no parameter */
293	void modes_type_d(IRC_CHANNEL_REC *channel, const char *setby,
294			  char type, char mode, char *arg, GString *newmode)
295	{
296		mode_set(channel->server, newmode, type, mode, FALSE);
297	}
298	
299	void modes_type_prefix(IRC_CHANNEL_REC *channel, const char *setby,
300			       char type, char mode, char *arg, GString *newmode)
301	{
302		int umode = (unsigned char) mode;
303	
304		if (g_ascii_strcasecmp(channel->server->nick, arg) == 0) {
305			/* see if we need to update channel->chanop */
306			const char *prefix =
307				g_hash_table_lookup(channel->server->isupport, "PREFIX");
308			if (prefix != NULL && *prefix == '(') {
309				prefix++;
310				while (*prefix != ')' && *prefix != '\0') {
311					if (*prefix == mode) {
312						channel->chanop = type == '+';
313						break;
314					}
315					if (*prefix == 'o')
316						break;
317					prefix++;
318				}
319			} else {
320				if (mode == 'o' || mode == 'O')
321					channel->chanop = type == '+';
322			}
323		}
324	
325		nick_mode_change(channel, arg, channel->server->modes[umode].prefix,
326				 type, setby);
327	}
328	
329	int channel_mode_is_set(IRC_CHANNEL_REC *channel, char mode)
330	{
331		g_return_val_if_fail(IS_IRC_CHANNEL(channel), FALSE);
332	
333		return channel->mode == NULL ? FALSE :
334			mode_is_set(channel->mode, mode);
335	}
336	
337	/* Parse channel mode string */
338	void parse_channel_modes(IRC_CHANNEL_REC *channel, const char *setby,
339				 const char *mode, int update_key)
340	{
341		IRC_SERVER_REC *server = channel->server;
342	        GString *newmode;
343		char *dup, *modestr, *arg, *curmode, type, *old_key;
344		int umode;
345	
346		g_return_if_fail(IS_IRC_CHANNEL(channel));
347		g_return_if_fail(mode != NULL);
348	
349		type = '+';
350		newmode = g_string_new(channel->mode);
351		old_key = update_key ? NULL : g_strdup(channel->key);
352	
353		dup = modestr = g_strdup(mode);
354		curmode = cmd_get_param(&modestr);
355		while (*curmode != '\0') {
356			if (HAS_MODE_ARG(server, type, *curmode)) {
357				/* get the argument for the mode. NOTE: We don't
358				   get the +k's argument when joining to channel. */
359				arg = cmd_get_param(&modestr);
360			} else {
361				arg = NULL;
362			}
363	
364			switch (*curmode) {
365			case '+':
366			case '-':
367				type = *curmode;
368				break;
369			default:
370				umode = (unsigned char) *curmode;
371				if (server->modes[umode].func != NULL) {
372					server->modes[umode].func(channel, setby,
373								  type, *curmode, arg,
374								  newmode);
375				} else {
376					/* Treat unknown modes as ones without params */
377					modes_type_d(channel, setby, type, *curmode,
378						     arg, newmode);
379				}
380			}
381	
382			curmode++;
383		}
384		g_free(dup);
385	
386		if (channel->key != NULL &&
387		    strchr(channel->mode, 'k') == NULL &&
388		    strchr(newmode->str, 'k') == NULL) {
389			/* join was used with key but there's no key set
390			   in channel modes.. */
391			g_free(channel->key);
392			channel->key = NULL;
393		} else if (!update_key && old_key != NULL) {
394			/* get the old one back, just in case it was replaced */
395			g_free(channel->key);
396			channel->key = old_key;
397			mode_set_arg(channel->server, newmode, '+', 'k', old_key, FALSE);
398			old_key = NULL;
399		}
400	
401		if (g_strcmp0(newmode->str, channel->mode) != 0) {
402			g_free(channel->mode);
403			channel->mode = g_strdup(newmode->str);
404	
405			signal_emit("channel mode changed", 2, channel, setby);
406		}
407	
408		g_string_free(newmode, TRUE);
409		g_free(old_key);
410	}
411	
412	/* add `mode' to `old' - return newly allocated mode.
413	   `channel' specifies if we're parsing channel mode and we should try
414	   to join mode arguments too. */
415	char *modes_join(IRC_SERVER_REC *server, const char *old,
416			 const char *mode, int channel)
417	{
418		GString *newmode;
419		char *dup, *modestr, *curmode, type;
420	
421	        g_return_val_if_fail(mode != NULL, NULL);
422	
423		type = '+';
424		newmode = g_string_new(old);
425	
426		dup = modestr = g_strdup(mode);
427		curmode = cmd_get_param(&modestr);
428		while (*curmode != '\0' && *curmode != ' ') {
429			if (*curmode == '+' || *curmode == '-') {
430				type = *curmode;
431				curmode++;
432				continue;
433			}
434	
435			if (!channel || !HAS_MODE_ARG(server, type, *curmode))
436				mode_set(server, newmode, type, *curmode, !channel);
437			else {
438				mode_set_arg(server, newmode, type, *curmode,
439					     cmd_get_param(&modestr), !channel);
440			}
441	
442			curmode++;
443		}
444		g_free(dup);
445	
446		modestr = newmode->str;
447		g_string_free(newmode, FALSE);
448		return modestr;
449	}
450	
451	/* Parse user mode string */
452	static void parse_user_mode(IRC_SERVER_REC *server, const char *modestr)
453	{
454		char *newmode, *oldmode;
455	
456		g_return_if_fail(IS_IRC_SERVER(server));
457		g_return_if_fail(modestr != NULL);
458	
459		newmode = modes_join(NULL, server->usermode, modestr, FALSE);
460		oldmode = server->usermode;
461		server->usermode = newmode;
462		server->server_operator = ((strchr(newmode, 'o') != NULL) || (strchr(newmode, 'O') != NULL));
463	
464		signal_emit("user mode changed", 2, server, oldmode);
465		g_free_not_null(oldmode);
466	}
467	
468	static void event_user_mode(IRC_SERVER_REC *server, const char *data)
469	{
470		char *params, *nick, *mode;
471	
472		g_return_if_fail(data != NULL);
473	
474		params = event_get_params(data, 3, NULL, &nick, &mode);
475		parse_user_mode(server, mode);
476	
477		g_free(params);
478	}
479	
480	static void event_mode(IRC_SERVER_REC *server, const char *data,
481			       const char *nick)
482	{
483		IRC_CHANNEL_REC *chanrec;
484		char *params, *channel, *mode;
485	
486		g_return_if_fail(data != NULL);
487	
488		params = event_get_params(data, 2 | PARAM_FLAG_GETREST,
489					  &channel, &mode);
490	
491		if (!server_ischannel(SERVER(server), channel)) {
492			/* user mode change */
493			parse_user_mode(server, mode);
494		} else {
495			/* channel mode change */
496			chanrec = irc_channel_find(server, channel);
497			if (chanrec != NULL)
498				parse_channel_modes(chanrec, nick, mode, TRUE);
499		}
500	
501		g_free(params);
502	}
503	
504	static void event_oper(IRC_SERVER_REC *server, const char *data)
505	{
506		const char *opermode;
507	
508		opermode = settings_get_str("opermode");
509	        if (*opermode != '\0')
510			irc_send_cmdv(server, "MODE %s %s", server->nick, opermode);
511	}
512	
513	static void event_away(IRC_SERVER_REC *server, const char *data)
514	{
515		g_return_if_fail(server != NULL);
516	
517		server->usermode_away = TRUE;
518		signal_emit("away mode changed", 1, server);
519	}
520	
521	static void event_unaway(IRC_SERVER_REC *server, const char *data)
522	{
523		g_return_if_fail(server != NULL);
524	
525		server->usermode_away = FALSE;
526		g_free_and_null(server->away_reason);
527		signal_emit("away mode changed", 1, server);
528	}
529	
530	static void sig_req_usermode_change(IRC_SERVER_REC *server, const char *data,
531					    const char *nick, const char *addr)
532	{
533		char *params, *target, *mode;
534	
535		g_return_if_fail(data != NULL);
536	
537		params = event_get_params(data, 2 | PARAM_FLAG_GETREST,
538					  &target, &mode);
539		if (!server_ischannel(SERVER(server), target)) {
540	                /* we requested a user mode change, save this */
541			mode = modes_join(NULL, server->wanted_usermode, mode, FALSE);
542	                g_free_not_null(server->wanted_usermode);
543			server->wanted_usermode = mode;
544		}
545	
546		g_free(params);
547	
548		signal_emit("event mode", 4, server, data, nick, addr);
549	}
550	
551	void channel_set_singlemode(IRC_CHANNEL_REC *channel, const char *nicks,
552				    const char *mode)
553	{
554		GString *str;
555		int num, modepos;
556		char **nick, **nicklist;
557	
558		g_return_if_fail(IS_IRC_CHANNEL(channel));
559		g_return_if_fail(nicks != NULL && mode != NULL);
560		if (*nicks == '\0') return;
561	
562		num = modepos = 0;
563		str = g_string_new(NULL);
564	
565		nicklist = g_strsplit(nicks, " ", -1);
566		for (nick = nicklist; *nick != NULL; nick++) {
567			if (**nick == '\0')
568				continue;
569	
570			if (num == 0)
571			{
572				g_string_printf(str, "MODE %s %s",
573						 channel->name, mode);
574				modepos = str->len;
575			} else {
576				/* insert the mode string */
577				g_string_insert(str, modepos, mode);
578			}
579	
580			g_string_append_printf(str, " %s", *nick);
581	
582			if (++num == channel->server->max_modes_in_cmd) {
583				/* max. modes / command reached, send to server */
584				irc_send_cmd(channel->server, str->str);
585				num = 0;
586			}
587		}
588		if (num > 0) irc_send_cmd(channel->server, str->str);
589	
590		g_strfreev(nicklist);
591		g_string_free(str, TRUE);
592	}
