32	static void check_join_failure(IRC_SERVER_REC *server, const char *channel)
33	{
34		CHANNEL_REC *chanrec;
35		char *chan2;
36	
37		if (channel[0] == '!' && channel[1] == '!')
38			channel++; /* server didn't understand !channels */
39	
40		chanrec = channel_find(SERVER(server), channel);
41		if (chanrec == NULL && channel[0] == '!' && strlen(channel) > 6) {
42			/* it probably replied with the full !channel name,
43			   find the channel with the short name.. */
44			chan2 = g_strdup_printf("!%s", channel+6);
45			chanrec = channel_find(SERVER(server), chan2);
46			g_free(chan2);
47		}
48	
49		if (chanrec != NULL && !chanrec->joined) {
50			chanrec->left = TRUE;
51			channel_destroy(chanrec);
52		}
53	}
