55	static void irc_server_event(IRC_SERVER_REC *server, const char *line)
56	{
57		char *params, *numeric, *channel;
58	
59		/* We'll be checking "4xx <your nick> <channel>" for channels
60		   which we haven't joined yet. 4xx are error codes and should
61		   indicate that the join failed. */
62		params = event_get_params(line, 3, &numeric, NULL, &channel);
63	
64		if (numeric[0] == '4')
65			check_join_failure(server, channel);
66	
67		g_free(params);
68	}
69	
70	static void event_no_such_channel(IRC_SERVER_REC *server, const char *data)
71	{
72		CHANNEL_REC *chanrec;
73		CHANNEL_SETUP_REC *setup;
74		char *params, *channel;
75	
76		params = event_get_params(data, 2, NULL, &channel);
77		chanrec = *channel == '!' && channel[1] != '\0' ?
78			channel_find(SERVER(server), channel) : NULL;
79	
80		if (chanrec != NULL) {
81	                /* !channel didn't exist, so join failed */
82			setup = channel_setup_find(chanrec->name,
83						   chanrec->server->connrec->chatnet);
84			if (setup != NULL && setup->autojoin) {
85				/* it's autojoin channel though, so create it */
86				irc_send_cmdv(server, "JOIN !%s", chanrec->name);
87				g_free(params);
88	                        return;
89			}
90		}
91	
92		check_join_failure(server, channel);
93		g_free(params);
94	}
