96	static void event_duplicate_channel(IRC_SERVER_REC *server, const char *data)
97	{
98		CHANNEL_REC *chanrec;
99		char *params, *channel, *p;
100	
101		g_return_if_fail(data != NULL);
102	
103		/* this new addition to ircd breaks completely with older
104		   "standards", "nick Duplicate ::!!channel ...." */
105		params = event_get_params(data, 3, NULL, NULL, &channel);
106		p = strchr(channel, ' ');
107		if (p != NULL) *p = '\0';
108	
109		if (channel[0] == '!') {
110			chanrec = channel_find(SERVER(server),
111					       channel+(channel[1] == '!'));
112			if (chanrec != NULL && !chanrec->names_got) {
113				chanrec->left = TRUE;
114				channel_destroy(chanrec);
115			}
116		}
117	
118		g_free(params);
119	}
