194	/* Find any unjoined channel that matches `channel'. Long channel names are
195	   also a bit problematic, so find a channel where start of the name matches. */
196	static IRC_CHANNEL_REC *channel_find_unjoined(IRC_SERVER_REC *server,
197						      const char *channel)
198	{
199		GSList *tmp;
200		int len;
201	
202		len = strlen(channel);
203		for (tmp = server->channels; tmp != NULL; tmp = tmp->next) {
204			IRC_CHANNEL_REC *rec = tmp->data;
205	
206			if (!IS_IRC_CHANNEL(rec) || rec->joined)
207				continue;
208	
209			if (g_ascii_strncasecmp(channel, rec->name, len) == 0 &&
210			    (len > 20 || rec->name[len] == '\0'))
211				return rec;
212		}
213	
214		return NULL;
215	}
216	
217	static void event_join(IRC_SERVER_REC *server, const char *data, const char *nick, const char *address)
218	{
219		char *params, *channel, *tmp, *shortchan;
220		IRC_CHANNEL_REC *chanrec;
221	
222		g_return_if_fail(data != NULL);
223	
224		if (g_ascii_strcasecmp(nick, server->nick) != 0) {
225			/* someone else joined channel, no need to do anything */
226			return;
227		}
228	
229		if (server->userhost == NULL)
230			server->userhost = g_strdup(address);
231	
232		params = event_get_params(data, 1, &channel);
233		tmp = strchr(channel, 7); /* ^G does something weird.. */
234		if (tmp != NULL) *tmp = '\0';
235	
236		if (*channel != '!' || strlen(channel) < 7)
237			shortchan = NULL;
238		else {
239			/* !channels have 5 chars long identification string before
240			   it's name, it's not known when /join is called so rename
241			   !channel here to !ABCDEchannel */
242			shortchan = g_strdup_printf("!%s", channel+6);
243			chanrec = channel_find_unjoined(server, shortchan);
244			if (chanrec != NULL) {
245				channel_change_name(CHANNEL(chanrec), channel);
246				g_free(chanrec->name);
247				chanrec->name = g_strdup(channel);
248			} else {
249				/* well, did we join it with full name? if so, and if
250				   this was the first short one, change it's name. */
251				chanrec = channel_find_unjoined(server, channel);
252				if (chanrec != NULL &&
253				    irc_channel_find(server, shortchan) == NULL) {
254					channel_change_visible_name(CHANNEL(chanrec),
255								    shortchan);
256				}
257			}
258		}
259	
260		chanrec = irc_channel_find(server, channel);
261		if (chanrec != NULL && chanrec->joined) {
262			/* already joined this channel - probably a broken proxy that
263			   forgot to send PART between */
264			chanrec->left = TRUE;
265			channel_destroy(CHANNEL(chanrec));
266			chanrec = NULL;
267		}
268	
269		if (chanrec == NULL) {
270			/* look again, because of the channel name cut issues. */
271			chanrec = channel_find_unjoined(server, channel);
272		}
273	
274		if (chanrec == NULL) {
275			/* didn't get here with /join command.. */
276			chanrec = irc_channel_create(server, channel, shortchan, TRUE);
277		}
278	
279		chanrec->joined = TRUE;
280		if (g_strcmp0(chanrec->name, channel) != 0) {
281	                g_free(chanrec->name);
282			chanrec->name = g_strdup(channel);
283		}
284	
285		g_free(shortchan);
286		g_free(params);
287	}
