289	static void event_part(IRC_SERVER_REC *server, const char *data, const char *nick)
290	{
291		char *params, *channel, *reason;
292		CHANNEL_REC *chanrec;
293	
294		g_return_if_fail(data != NULL);
295	
296		if (g_ascii_strcasecmp(nick, server->nick) != 0) {
297			/* someone else part, no need to do anything here */
298			return;
299		}
300	
301		params = event_get_params(data, 2, &channel, &reason);
302	
303		chanrec = channel_find(SERVER(server), channel);
304		if (chanrec != NULL && chanrec->joined) {
305			chanrec->left = TRUE;
306			channel_destroy(chanrec);
307		}
308	
309		g_free(params);
310	}
311	
312	static void event_kick(IRC_SERVER_REC *server, const char *data)
313	{
314		CHANNEL_REC *chanrec;
315		char *params, *channel, *nick, *reason;
316	
317		g_return_if_fail(data != NULL);
318	
319		params = event_get_params(data, 3, &channel, &nick, &reason);
320	
321		if (g_ascii_strcasecmp(nick, server->nick) != 0) {
322			/* someone else was kicked, no need to do anything */
323			g_free(params);
324			return;
325		}
326	
327		chanrec = channel_find(SERVER(server), channel);
328		if (chanrec != NULL) {
329			irc_server_purge_output(server, channel);
330			chanrec->kicked = TRUE;
331			channel_destroy(chanrec);
332		}
333	
334		g_free(params);
335	}
336	
337	static void event_invite(IRC_SERVER_REC *server, const char *data)
338	{
339		char *params, *nick, *channel, *shortchan;
340	
341		g_return_if_fail(data != NULL);
342	
343		params = event_get_params(data, 2, &nick, &channel);
344	
345		if (server->nick_comp_func(nick, server->nick) != 0) {
346			/* someone else was invited, no need to do anything */
347			g_free(params);
348			return;
349		}
350	
351		if (irc_channel_find(server, channel) == NULL) {
352	                /* check if we're supposed to autojoin this channel */
353			CHANNEL_SETUP_REC *setup;
354	
355			setup = channel_setup_find(channel, server->connrec->chatnet);
356			if (setup == NULL && channel[0] == '!' &&
357			    strlen(channel) > 6) {
358				shortchan = g_strdup_printf("!%s", channel+6);
359				setup = channel_setup_find(shortchan,
360							   server->connrec->chatnet);
361				g_free(shortchan);
362			}
363			if (setup != NULL && setup->autojoin && settings_get_bool("join_auto_chans_on_invite"))
364				server->channels_join(SERVER(server), channel, TRUE);
365		}
366	
367		g_free_not_null(server->last_invite);
368		server->last_invite = g_strdup(channel);
369		g_free(params);
370	}
