372	void channel_events_init(void)
373	{
374		settings_add_bool("misc", "join_auto_chans_on_invite", TRUE);
375	
376		signal_add_last("server event", (SIGNAL_FUNC) irc_server_event);
377		signal_add_first("event 403", (SIGNAL_FUNC) event_no_such_channel); /* no such channel */
378		signal_add_first("event 407", (SIGNAL_FUNC) event_duplicate_channel); /* duplicate channel */
379	
380		signal_add("event topic", (SIGNAL_FUNC) event_topic);
381		signal_add_first("event join", (SIGNAL_FUNC) event_join);
382		signal_add("event part", (SIGNAL_FUNC) event_part);
383		signal_add("event kick", (SIGNAL_FUNC) event_kick);
384		signal_add("event invite", (SIGNAL_FUNC) event_invite);
385		signal_add("event 332", (SIGNAL_FUNC) event_topic_get);
386		signal_add("event 333", (SIGNAL_FUNC) event_topic_info);
387	}
388	
389	void channel_events_deinit(void)
390	{
391		signal_remove("server event", (SIGNAL_FUNC) irc_server_event);
392		signal_remove("event 403", (SIGNAL_FUNC) event_no_such_channel); /* no such channel */
393		signal_remove("event 407", (SIGNAL_FUNC) event_duplicate_channel); /* duplicate channel */
394	
395		signal_remove("event topic", (SIGNAL_FUNC) event_topic);
396		signal_remove("event join", (SIGNAL_FUNC) event_join);
397		signal_remove("event part", (SIGNAL_FUNC) event_part);
398		signal_remove("event kick", (SIGNAL_FUNC) event_kick);
399		signal_remove("event invite", (SIGNAL_FUNC) event_invite);
400		signal_remove("event 332", (SIGNAL_FUNC) event_topic_get);
401		signal_remove("event 333", (SIGNAL_FUNC) event_topic_info);
402	}
