121	static void channel_change_topic(IRC_SERVER_REC *server, const char *channel,
122					 const char *topic, const char *setby,
123					 time_t settime)
124	{
125		CHANNEL_REC *chanrec;
126		char *recoded = NULL;
127	
128		chanrec = channel_find(SERVER(server), channel);
129		if (chanrec == NULL) return;
130		/* the topic may be send out encoded, so we need to
131		   recode it back or /topic <tab> will not work properly */
132		recoded = recode_in(SERVER(server), topic, channel);
133		if (topic != NULL) {
134			g_free_not_null(chanrec->topic);
135			chanrec->topic = recoded == NULL ? NULL : g_strdup(recoded);
136		}
137		g_free(recoded);
138	
139		g_free_not_null(chanrec->topic_by);
140		chanrec->topic_by = g_strdup(setby);
141	
142		if (chanrec->topic_by == NULL) {
143			/* ensure invariant topic_time > 0 <=> topic_by != NULL.
144			   this could be triggered by a topic command without sender */
145			chanrec->topic_time = 0;
146		} else {
147			chanrec->topic_time = settime;
148		}
149	
150		signal_emit("channel topic changed", 1, chanrec);
