51			irc_send_cmdv(server, "CAP REQ %s", cap);
52			return TRUE;
53		} else if (!enable && i_slist_find_string(server->cap_active, cap)) {
54			char *negcap = g_strdup_printf("-%s", cap);
55	
56			signal_emit("server cap req", 2, server, negcap);
57			irc_send_cmdv(server, "CAP REQ %s", negcap);
58	
59			g_free(negcap);
60			return TRUE;
61		}
62	
63		return FALSE;
64	}
65	
66	void irc_cap_finish_negotiation (IRC_SERVER_REC *server)
67	{
68		if (server->cap_complete)
69			return;
70	
71		server->cap_complete = TRUE;
72		irc_send_cmd_now(server, "CAP END");
73	
74		signal_emit("server cap end", 1, server);
75	}
76	
77	static void cap_emit_signal (IRC_SERVER_REC *server, char *cmd, char *args)
78	{
79		char *signal_name;
80	
81		signal_name = g_strdup_printf("server cap %s %s", cmd, args? args: "");
82		signal_emit(signal_name, 1, server);
83		g_free(signal_name);
84	}
85	
86	static gboolean parse_cap_name(char *name, char **key, char **val)
87	{
88		const char *eq;
89	
90		g_return_val_if_fail(name != NULL, FALSE);
91		g_return_val_if_fail(name[0] != '\0', FALSE);
92	
93		eq = strchr(name, '=');
94		/* KEY only value */
95		if (eq == NULL) {
96			*key = g_strdup(name);
97			*val = NULL;
98		/* Some values are in a KEY=VALUE form, parse them */
99		} else {
100			*key = g_strndup(name, (gsize)(eq - name));
101			*val = g_strdup(eq + 1);
102		}
103	
104		return TRUE;
105	}
106	
107	static void event_cap (IRC_SERVER_REC *server, char *args, char *nick, char *address)
108	{
109		GSList *tmp;
110		GString *cmd;
111		char *params, *evt, *list, *star, **caps;
112		int i, caps_length, disable, avail_caps, multiline;
113	
114		params = event_get_params(args, 4, NULL, &evt, &star, &list);
115		if (params == NULL)
116			return;
117	
118		/* Multiline responses have an additional parameter and we have to do
119		 * this stupid dance to parse them */
120		if (!g_ascii_strcasecmp(evt, "LS") && !strcmp(star, "*")) {
121			multiline = TRUE;
122		}
123		/* This branch covers the '*' parameter isn't present, adjust the
124		 * parameter pointer to compensate for this */
125		else if (list[0] == '\0') {
126			multiline = FALSE;
127			list = star;
128		}
129		/* Malformed request, terminate the negotiation */
130		else {
131			irc_cap_finish_negotiation(server);
132			g_free(params);
133			g_warn_if_reached();
134			return;
135		}
136	
137		/* The table is created only when needed */
138		if (server->cap_supported == NULL) {
139			server->cap_supported = g_hash_table_new_full(g_str_hash,
140								      g_str_equal,
141								      g_free, g_free);
142		}
143	
144		/* Strip the trailing whitespaces before splitting the string, some servers send responses with
145		 * superfluous whitespaces that g_strsplit the interprets as tokens */
146		caps = g_strsplit(g_strchomp(list), " ", -1);
147		caps_length = g_strv_length(caps);
148	
149		if (!g_ascii_strcasecmp(evt, "LS")) {
150			if (!server->cap_in_multiline) {
151				/* Throw away everything and start from scratch */
152				g_hash_table_remove_all(server->cap_supported);
153			}
154	
155			server->cap_in_multiline = multiline;
156	
157			/* Create a list of the supported caps */
158			for (i = 0; i < caps_length; i++) {
159				char *key, *val;
160	
161				if (!parse_cap_name(caps[i], &key, &val)) {
162					g_warning("Invalid CAP %s key/value pair", evt);
163					continue;
164				}
165	
166				if (g_hash_table_lookup_extended(server->cap_supported, key, NULL, NULL)) {
167					/* The specification doesn't say anything about
168					 * duplicated values, let's just warn the user */
169					g_warning("The server sent the %s capability twice", key);
170				}
171				g_hash_table_replace(server->cap_supported, key, val);
172			}
173	
174			/* A multiline response is always terminated by a normal one,
175			 * wait until we receive that one to require any CAP */
176			if (multiline == FALSE) {
177				/* No CAP has been requested */
178				if (server->cap_queue == NULL) {
179					irc_cap_finish_negotiation(server);
180				}
181				else {
182					cmd = g_string_new("CAP REQ :");
183	
184					avail_caps = 0;
185	
186					/* To process the queue in order, we need to reverse the stack once */
187					server->cap_queue = g_slist_reverse(server->cap_queue);
188	
189					/* Check whether the cap is supported by the server */
190					for (tmp = server->cap_queue; tmp != NULL; tmp = tmp->next) {
191						if (g_hash_table_lookup_extended(server->cap_supported, tmp->data, NULL, NULL)) {
192							if (avail_caps > 0)
193								g_string_append_c(cmd, ' ');
194							g_string_append(cmd, tmp->data);
195	
196							avail_caps++;
197						}
198					}
199	
200					/* Clear the queue here */
201					i_slist_free_full(server->cap_queue, (GDestroyNotify) g_free);
202					server->cap_queue = NULL;
203	
204					/* If the server doesn't support any cap we requested close the negotiation here */
205					if (avail_caps > 0) {
206						signal_emit("server cap req", 2, server, cmd->str + sizeof("CAP REQ :") - 1);
207						irc_send_cmd_now(server, cmd->str);
208					} else {
209						irc_cap_finish_negotiation(server);
210					}
211	
212					g_string_free(cmd, TRUE);
213				}
214			}
215		}
216		else if (!g_ascii_strcasecmp(evt, "ACK")) {
217			int got_sasl = FALSE;
218	
219			/* Emit a signal for every ack'd cap */
220			for (i = 0; i < caps_length; i++) {
221				disable = (*caps[i] == '-');
222	
223				if (disable)
224					server->cap_active =
225					    i_slist_delete_string(server->cap_active, caps[i] + 1, g_free);
226				else if (!i_slist_find_string(server->cap_active, caps[i]))
227					server->cap_active = g_slist_prepend(server->cap_active, g_strdup(caps[i]));
228	
229				if (!strcmp(caps[i], "sasl"))
230					got_sasl = TRUE;
231	
232				cap_emit_signal(server, "ack", caps[i]);
233			}
234	
235			/* Hopefully the server has ack'd all the caps requested and we're ready to terminate the
236			 * negotiation, unless sasl was requested. In this case we must not terminate the negotiation
237			 * until the sasl handshake is over. */
238			if (got_sasl == FALSE)
239				irc_cap_finish_negotiation(server);
240		}
241		else if (!g_ascii_strcasecmp(evt, "NAK")) {
242			g_warning("The server answered with a NAK to our CAP request, this should not happen");
243	
244			/* A NAK'd request means that a required cap can't be enabled or disabled, don't update the
245			 * list of active caps and notify the listeners. */
246			for (i = 0; i < caps_length; i++)
247				cap_emit_signal(server, "nak", caps[i]);
248		}
249		else if (!g_ascii_strcasecmp(evt, "NEW")) {
250			for (i = 0; i < caps_length; i++) {
251				char *key, *val;
252	
253				if (!parse_cap_name(caps[i], &key, &val)) {
254					g_warning("Invalid CAP %s key/value pair", evt);
255					continue;
256				}
257	
258				g_hash_table_replace(server->cap_supported, key, val);
259				cap_emit_signal(server, "new", key);
260			}
261		}
262		else if (!g_ascii_strcasecmp(evt, "DEL")) {
263			for (i = 0; i < caps_length; i++) {
264				char *key, *val;
265	
266				if (!parse_cap_name(caps[i], &key, &val)) {
267					g_warning("Invalid CAP %s key/value pair", evt);
268					continue;
269				}
270	
271				g_hash_table_remove(server->cap_supported, key);
272				cap_emit_signal(server, "delete", key);
273				/* The server removed this CAP, remove it from the list
274				 * of the active ones if we had requested it */
275				server->cap_active = i_slist_delete_string(server->cap_active, key, g_free);
276				/* We don't transfer the ownership of those two
277				 * variables this time, just free them when we're done. */
278				g_free(key);
279				g_free(val);
280			}
281		}
282		else if (!g_ascii_strcasecmp(evt, "LIST")) {
283			/* do nothing, fe-cap will handle it */
284		}
285		else {
286			g_warning("Unhandled CAP subcommand %s", evt);
287		}
288	
289		g_strfreev(caps);
290		g_free(params);
291	}
292	
293	static void event_invalid_cap (IRC_SERVER_REC *server, const char *data, const char *from)
294	{
295		/* The server didn't understand one (or more) requested caps, terminate the negotiation.
296		 * This could be handled in a graceful way but since it shouldn't really ever happen this seems a
297		 * good way to deal with 410 errors. */
298		server->cap_complete = FALSE;
299		irc_send_cmd_now(server, "CAP END");
300	}
301	
302	void irc_cap_init (void)
303	{
304		signal_add_first("event cap", (SIGNAL_FUNC) event_cap);
305		signal_add_first("event 410", (SIGNAL_FUNC) event_invalid_cap);
306	}
307	
308	void irc_cap_deinit (void)
309	{
310		signal_remove("event cap", (SIGNAL_FUNC) event_cap);
311		signal_remove("event 410", (SIGNAL_FUNC) event_invalid_cap);
312	}
