33	typedef struct {
34		char *name;
35	        int refcount;
36	} CTCP_CMD_REC;
37	
38	static GSList *ctcp_cmds;
39	
40	static CTCP_CMD_REC *ctcp_cmd_find(const char *name)
41	{
42		GSList *tmp;
43	
44		for (tmp = ctcp_cmds; tmp != NULL; tmp = tmp->next) {
45			CTCP_CMD_REC *rec = tmp->data;
46	
47			if (g_ascii_strcasecmp(rec->name, name) == 0)
48	                        return rec;
49		}
50	
51	        return NULL;
52	}
53	
54	void ctcp_register(const char *name)
55	{
56		CTCP_CMD_REC *rec;
57	
58		rec = ctcp_cmd_find(name);
59		if (rec == NULL) {
60			rec = g_new0(CTCP_CMD_REC, 1);
61			rec->name = g_ascii_strup(name, -1);
62	
63			ctcp_cmds = g_slist_append(ctcp_cmds, rec);
64		}
65	
66		rec->refcount++;
67	}
68	
69	static void ctcp_cmd_destroy(CTCP_CMD_REC *rec)
70	{
71		ctcp_cmds = g_slist_remove(ctcp_cmds, rec);
72		g_free(rec->name);
73		g_free(rec);
74	}
75	
76	void ctcp_unregister(const char *name)
77	{
78		CTCP_CMD_REC *rec;
79	
80		rec = ctcp_cmd_find(name);
81		if (rec != NULL && --rec->refcount == 0)
82	                ctcp_cmd_destroy(rec);
83	}
84	
85	static void ctcp_queue_clean(IRC_SERVER_REC *server)
86	{
87		GSList *tmp, *next;
88	
89		for (tmp = server->ctcpqueue; tmp != NULL; tmp = next) {
90			next = tmp->next;
91			if (!server_idle_find(server, GPOINTER_TO_INT(tmp->data))) {
92				server->ctcpqueue =
93					g_slist_remove(server->ctcpqueue, tmp->data);
94			}
95		}
96	}
