98	/* Send CTCP reply with flood protection */
99	void ctcp_send_reply(IRC_SERVER_REC *server, const char *data)
100	{
101		int tag;
102	
103		g_return_if_fail(server != NULL);
104		g_return_if_fail(data != NULL);
105	
106		ctcp_queue_clean(server);
107	
108		if ((int)g_slist_length(server->ctcpqueue) >=
109		    settings_get_int("max_ctcp_queue"))
110			return;
111	
112		/* Add to first in idle queue */
113		tag = server_idle_add(server, data);
114		server->ctcpqueue =
115			g_slist_append(server->ctcpqueue, GINT_TO_POINTER(tag));
116	}
