118	/* CTCP ping */
119	static void ctcp_ping(IRC_SERVER_REC *server, const char *data,
120			      const char *nick)
121	{
122		char *str;
123	
124		g_return_if_fail(data != NULL);
125		g_return_if_fail(server != NULL);
126		g_return_if_fail(nick != NULL);
127	
128		if (strlen(data) > 100) {
129			/* Yes, this is kind of a kludge, but people who PING you
130			   with messages this long deserve not to get the reply.
131	
132			   The problem with long messages is that when you send lots
133			   of data to server, it's input buffer gets full and you get
134			   killed from server because of "excess flood".
135	
136			   Irssi's current flood protection doesn't count the message
137			   length, but even if it did, the CTCP flooder would still
138			   be able to at least slow down your possibility to send
139			   messages to server. */
140	                return;
141		}
142	
143		str = g_strdup_printf("NOTICE %s :\001PING %s\001", nick, data);
144		ctcp_send_reply(server, str);
145		g_free(str);
146	}
147	
148	static void ctcp_send_parsed_reply(IRC_SERVER_REC *server, const char *nick,
149					   const char *cmd, const char *args)
150	{
151		char *str, *pstr;
152	
153		g_return_if_fail(server != NULL);
154		g_return_if_fail(nick != NULL);
155	
156		if (*args == '\0')
157	                return;
158	
159		pstr = parse_special_string(args, SERVER(server), NULL, "", NULL, 0);
160		str = g_strdup_printf("NOTICE %s :\001%s %s\001", nick, cmd, pstr);
161		ctcp_send_reply(server, str);
162		g_free(str);
163		g_free(pstr);
164	}
165	
166	/* CTCP version */
167	static void ctcp_version(IRC_SERVER_REC *server, const char *data,
168				 const char *nick)
169	{
170		ctcp_send_parsed_reply(server, nick, "VERSION",
171				       settings_get_str("ctcp_version_reply"));
172	}
173	
174	/* CTCP time */
175	static void ctcp_time(IRC_SERVER_REC *server, const char *data,
176			      const char *nick)
177	{
178		char *str, *reply;
179	
180		g_return_if_fail(server != NULL);
181		g_return_if_fail(nick != NULL);
182	
183	        reply = my_asctime(time(NULL));
184		str = g_strdup_printf("NOTICE %s :\001TIME %s\001", nick, reply);
185		ctcp_send_reply(server, str);
186		g_free(str);
187		g_free(reply);
188	}
189	
190	/* CTCP userinfo */
191	static void ctcp_userinfo(IRC_SERVER_REC *server, const char *data,
192				  const char *nick)
193	{
194		ctcp_send_parsed_reply(server, nick, "USERINFO",
195				       settings_get_str("ctcp_userinfo_reply"));
196	}
197	
198	/* CTCP clientinfo */
199	static void ctcp_clientinfo(IRC_SERVER_REC *server, const char *data,
200				    const char *nick)
201	{
202		GString *str;
203	        GSList *tmp;
204	
205		g_return_if_fail(server != NULL);
206		g_return_if_fail(nick != NULL);
207	
208		str = g_string_new(NULL);
209	        g_string_printf(str, "NOTICE %s :\001CLIENTINFO", nick);
210		for (tmp = ctcp_cmds; tmp != NULL; tmp = tmp->next) {
211			CTCP_CMD_REC *rec = tmp->data;
212	
213	                g_string_append_c(str, ' ');
214	                g_string_append(str, rec->name);
215		}
216		g_string_append_c(str, '\001');
217	
218		ctcp_send_reply(server, str->str);
219		g_string_free(str, TRUE);
220	}
221	
222	static void ctcp_msg(IRC_SERVER_REC *server, const char *data,
223			     const char *nick, const char *addr, const char *target)
224	{
225		char *args, *str;
226	
227		if (g_ascii_strncasecmp(data, "ACTION ", 7) == 0) {
228	                /* special treatment for actions */
229			signal_emit("ctcp action", 5, server, data+7,
230				    nick, addr, target);
231	                return;
232		}
233	
234		if (ignore_check(SERVER(server), nick, addr, target, data, MSGLEVEL_CTCPS))
235			return;
236	
237		str = g_strconcat("ctcp msg ", data, NULL);
238		args = strchr(str+9, ' ');
239		if (args != NULL) *args++ = '\0'; else args = "";
240	
241		ascii_strdown(str+9);
242		if (!signal_emit(str, 5, server, args, nick, addr, target)) {
243			signal_emit("default ctcp msg", 5,
244				    server, data, nick, addr, target);
245		}
246		g_free(str);
247	}
248	
249	static void ctcp_reply(IRC_SERVER_REC *server, const char *data,
250			       const char *nick, const char *addr, const char *target)
251	{
252		char *args, *str;
253	
254		if (ignore_check(SERVER(server), nick, addr, target, data, MSGLEVEL_CTCPS))
255			return;
256	
257		str = g_strconcat("ctcp reply ", data, NULL);
258		args = strchr(str+11, ' ');
259		if (args != NULL) *args++ = '\0'; else args = "";
260	
261		ascii_strdown(str+11);
262		if (!signal_emit(str, 5, server, args, nick, addr, target)) {
263			signal_emit("default ctcp reply", 5,
264				    server, data, nick, addr, target);
265		}
266		g_free(str);
267	}
268	
269	static void event_privmsg(IRC_SERVER_REC *server, const char *data,
270				  const char *nick, const char *addr)
271	{
272		char *params, *target, *msg;
273		int len;
274	
275		g_return_if_fail(data != NULL);
276	
277		params = event_get_params(data, 2, &target, &msg);
278	
279		/* handle only ctcp messages.. */
280		if (*msg == 1) {
281			/* remove the \001 at beginning and end */
282			msg++;
283			len = strlen(msg);
284			if (msg[len-1] == '\001')
285				msg[len-1] = '\0';
286	
287			signal_emit("ctcp msg", 5, server, msg, nick, addr, target);
288			signal_stop();
289		}
290	
291		g_free(params);
292	}
293	
294	static void event_notice(IRC_SERVER_REC *server, const char *data,
295				 const char *nick, const char *addr)
296	{
297		char *params, *target, *ptr, *msg;
298	
299		g_return_if_fail(data != NULL);
300	
301		params = event_get_params(data, 2, &target, &msg);
302	
303		/* handle only ctcp replies */
304		if (*msg == 1) {
305			ptr = strrchr(++msg, 1);
306			if (ptr != NULL) *ptr = '\0';
307	
308			signal_emit("ctcp reply", 5, server, msg, nick, addr, target);
309			signal_stop();
310		}
311	
312		g_free(params);
313	}
314	
315	static void sig_disconnected(IRC_SERVER_REC *server)
316	{
317		g_return_if_fail(server != NULL);
318	
319		if (!IS_IRC_SERVER(server))
320			return;
321	
322		g_slist_free(server->ctcpqueue);
323	        server->ctcpqueue = NULL;
324	}
325	
326	void ctcp_init(void)
327	{
328		ctcp_cmds = NULL;
329	
330		settings_add_str("misc", "ctcp_version_reply",
331				 PACKAGE_TARNAME" v$J - running on $sysname $sysarch");
332		settings_add_str("misc", "ctcp_userinfo_reply", "$Y");
333		settings_add_int("flood", "max_ctcp_queue", 5);
334	
335		signal_add("server disconnected", (SIGNAL_FUNC) sig_disconnected);
336		signal_add_first("event privmsg", (SIGNAL_FUNC) event_privmsg);
337		signal_add_first("event notice", (SIGNAL_FUNC) event_notice);
338		signal_add("ctcp msg", (SIGNAL_FUNC) ctcp_msg);
339		signal_add("ctcp reply", (SIGNAL_FUNC) ctcp_reply);
340		signal_add("ctcp msg ping", (SIGNAL_FUNC) ctcp_ping);
341		signal_add("ctcp msg version", (SIGNAL_FUNC) ctcp_version);
342		signal_add("ctcp msg time", (SIGNAL_FUNC) ctcp_time);
343		signal_add("ctcp msg userinfo", (SIGNAL_FUNC) ctcp_userinfo);
344		signal_add("ctcp msg clientinfo", (SIGNAL_FUNC) ctcp_clientinfo);
345	
346	        ctcp_register("ping");
347	        ctcp_register("version");
348	        ctcp_register("time");
349	        ctcp_register("userinfo");
350	        ctcp_register("clientinfo");
351	}
352	
353	void ctcp_deinit(void)
354	{
355		while (ctcp_cmds != NULL)
356			ctcp_cmd_destroy(ctcp_cmds->data);
357	
358		signal_remove("server disconnected", (SIGNAL_FUNC) sig_disconnected);
359		signal_remove("event privmsg", (SIGNAL_FUNC) event_privmsg);
360		signal_remove("event notice", (SIGNAL_FUNC) event_notice);
361		signal_remove("ctcp msg", (SIGNAL_FUNC) ctcp_msg);
362		signal_remove("ctcp reply", (SIGNAL_FUNC) ctcp_reply);
363		signal_remove("ctcp msg ping", (SIGNAL_FUNC) ctcp_ping);
364		signal_remove("ctcp msg version", (SIGNAL_FUNC) ctcp_version);
365		signal_remove("ctcp msg time", (SIGNAL_FUNC) ctcp_time);
366		signal_remove("ctcp msg userinfo", (SIGNAL_FUNC) ctcp_userinfo);
367		signal_remove("ctcp msg clientinfo", (SIGNAL_FUNC) ctcp_clientinfo);
368	}
